import{cargoRescueBodyClear}from'./rescue-host-readers.mjs';
import {verifySevenSceneMaterial} from '../../world/cargo-seven-scene-geometry.mjs';
const approaches=new WeakMap(),owned=new WeakMap(),PINS={"APPROACH_ROOT_SELECTION.json": "fd741e556267ceda492e4150c2ac672380bace9b138bba0ddf87d6f72fd5b12d", "NEW_CHEST_CONTACT_PROPOSAL.json": "2fcf9532ffa5fdcfacf6cce08eeeec7c33fb069a7b43731836318339f6ed7222", "NEW_CHEST_APPROACH_PROPOSAL.json": "48863fa9b99e6b45ee4ec4c3adc86f093382a08621e41b3e99bb4d205a0647e1", "ROOT_SELECTION.json": "05bf5c4322fa50bc0ebfd703b547dfbdb34145bc6bc3c17328c9bccb6cb11e52", "CHEST_APPROACH_RLE.json": "3ca9ef6b38c84acf15cdbee10579be85708f7e23c01ed93bd1417855d8ea27f9"};
const bytes=x=>x instanceof ArrayBuffer?new Uint8Array(x.slice(0)):x instanceof Uint8Array?new Uint8Array(x):null;
const hash=async b=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',b))].map(x=>x.toString(16).padStart(2,'0')).join('');
export async function loadCargoChestPhysics({readBytes}){const data={};for(const[name,pin]of Object.entries(PINS)){const b=bytes(await readBytes('chest-physics-r1/'+name));if(!b||await hash(b)!==pin)throw Error('CHEST_PHYSICS_PIN');data[name]=JSON.parse(new TextDecoder().decode(b))}if(data['ROOT_SELECTION.json'].status!=='ROOT_SELECTED_NEW_CHEST_PHYSICAL_BASE_AND_ORIGINAL_ART')throw Error('CHEST_PHYSICS_SELECTION');const rows=data['NEW_CHEST_CONTACT_PROPOSAL.json'].rows;if(data['APPROACH_ROOT_SELECTION.json'].status!=='ROOT_SELECTED_EIGHT_CHEST_NATURAL_APPROACH_R1')throw Error('CHEST_APPROACH_SELECTION');const a=Object.freeze({revision:'CARGO_EIGHT_CHEST_SELECTED_PHYSICS_APPROACH_R1'});owned.set(a,rows);approaches.set(a,new Map(data['CHEST_APPROACH_RLE.json'].rows.map(r=>[r.id,r])));return a}
export const isCargoChestPhysics=a=>owned.has(a);
export function chestPhysicsAllowsFoot(a,spec,material,foot){const rows=owned.get(a);if(!rows||!verifyEightSceneMaterial(spec,material)||!Array.isArray(foot)||foot.length!==2||!foot.every(Number.isInteger)||foot[0]<0||foot[1]<0||foot[0]>=1536||foot[1]>=1024)return false;const scene=rows.filter(r=>r.sceneId===spec.sceneId);if(spec.sceneId==='ship_rescue')return cargoRescueBodyClear(spec.sceneId,foot)&&material.isSafeFoot(foot);const physicalBaselineMask=originalSevenMaskForRescueBridge(material)??material.footMaskSHA256;if(!scene.length||scene.some(r=>!Object.values(r.states).some(s=>s.currentMaskSHA===physicalBaselineMask)))return false;return !scene.some(r=>{const[l,t,end,bottom]=r.newForbiddenFootCenterRectHalfOpen;return foot[0]>=l&&foot[0]<end&&foot[1]>=t&&foot[1]<bottom})}
export function chestPhysicsFootClear(a,sceneId,foot){const rows=owned.get(a);if(!rows||!Array.isArray(foot)||foot.length!==2||!foot.every(Number.isInteger)||foot[0]<0||foot[1]<0||foot[0]>=1536||foot[1]>=1024)return false;const scene=rows.filter(r=>r.sceneId===sceneId);return (sceneId==='ship_rescue'?cargoRescueBodyClear(sceneId,foot):!!scene.length)&&!scene.some(r=>{const[l,t,end,bottom]=r.newForbiddenFootCenterRectHalfOpen;return foot[0]>=l&&foot[0]<end&&foot[1]>=t&&foot[1]<bottom})}
export function allowsCargoChestInteraction(a,id,spec,material,foot,facing){const row=approaches.get(a)?.get(id);return !!row&&row.sceneId===spec?.sceneId&&row.imageSHA===material?.artSHA256&&row.maskSHAs.includes(originalSevenMaskForRescueBridge(material)??material?.footMaskSHA256)&&row.facings.includes(facing)&&chestPhysicsAllowsFoot(a,spec,material,foot)&&material.isSafeFoot(foot)===true&&row.runsHalfOpen.some(([y,l,end])=>foot[1]===y&&foot[0]>=l&&foot[0]<end)}
export function disposeCargoChestPhysics(a){owned.delete(a);approaches.delete(a)}
